'use client'
import { api } from '../lib/api'
export function UserCard({ id, url }) {
  async function load() {
    const { data } = await api.get(`/users/${id}`)
    const external = await fetch('https://api.stripe.com/v1/charges')
    const dynamic = await fetch(url)
    const orders = await fetch(`${process.env.API_URL}/api/users/${id}/orders`)
    return [data, external, dynamic, orders]
  }
  return null
}

