'use client'
import { useEffect, useState } from 'react'
import { io } from 'socket.io-client'
const socket = io()
export function Chat() {
  const [messages, setMessages] = useState([])
  useEffect(() => {
    socket.on('message', (m) => {
      setMessages((prev) => [...prev, m])
    })
  }, [])
  function send(text) {
    socket.emit('message', text)
  }
  return null
}

